create policy scene_areas_member_select on public.scene_areas for select to authenticated using (exists (select 1 from public.scenes s join public.campaign_members m on m.campaign_id = s.campaign_id where s.id = scene_areas.scene_id and m.user_id = auth.uid()) or exists (select 1 from public.scenes s join public.campaigns c on c.id = s.campaign_id where s.id = scene_areas.scene_id and c.owner_id = auth.uid()));
create policy scene_areas_gm_write on public.scene_areas for all to authenticated using (exists (select 1 from public.scenes s join public.campaign_members m on m.campaign_id = s.campaign_id where s.id = scene_areas.scene_id and m.user_id = auth.uid() and m.role = 'gm'::campaign_role) or exists (select 1 from public.scenes s join public.campaigns c on c.id = s.campaign_id where s.id = scene_areas.scene_id and c.owner_id = auth.uid())) with check (exists (select 1 from public.scenes s join public.campaign_members m on m.campaign_id = s.campaign_id where s.id = scene_areas.scene_id and m.user_id = auth.uid() and m.role = 'gm'::campaign_role) or exists (select 1 from public.scenes s join public.campaigns c on c.id = s.campaign_id where s.id = scene_areas.scene_id and c.owner_id = auth.uid()));
